function countNodes(root: TreeNode | null): number {
  if (!root) return 0;
  let lh = 0, rh = 0;
  for (let n: TreeNode | null = root; n; n = n.left) lh++;
  for (let n: TreeNode | null = root; n; n = n.right) rh++;
  if (lh === rh) return 2 ** lh - 1; // perfect subtree
  return 1 + countNodes(root.left) + countNodes(root.right);
}

